import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'

const read = (path: string) =>
  readFileSync(new URL(`../../../${path}`, import.meta.url), 'utf8')

/** The --logo-* values in the theme's block (`:root` or `.dark`). */
function logoVariables(css: string, selector: string) {
  const start = css.indexOf(`\n${selector} {`)
  const block = css.slice(start, css.indexOf('\n}', start))
  return Object.fromEntries(
    [...block.matchAll(/--logo-([\w-]+):\s*([^;]+);/g)].map((m) => [
      m[1],
      m[2]!.trim(),
    ]),
  )
}

// public/brand is generated by scripts/brand-assets.ts, which keeps its own
// copy of the colours. This fails when it and the theme disagree.
describe('public/brand colours', () => {
  const css = read('app/assets/css/tailwind.css')
  const light = logoVariables(css, ':root')
  const dark = { ...light, ...logoVariables(css, '.dark') }

  it.each([
    ['light', light],
    ['dark', dark],
  ])('mark-%s.svg uses the theme colours', (theme, vars) => {
    const svg = read(`public/brand/mark-${theme}.svg`)
    expect(svg).toContain(
      `fill="${vars['wall']}" fill-opacity="${vars['wall-opacity']}"`,
    )
    expect(svg).toContain(`stop-color="${vars['glass-from']}"`)
    expect(svg).toContain(`stop-color="${vars['glass-via']}"`)
    expect(svg).toContain(`stop-color="${vars['glass-to']}"`)
    expect(svg).toContain(`stroke="${vars['edge']}"`)
  })
})
